const financeJournals=financeJournalSamples.map(([id,title,date,status,memo,source,ref,amount,lineCount],index)=>({id,title,date,status,memo,source,ref,amount,lineCount,approval:index===2?'pending':'',createdBy:'Farah Ahmed',postedBy:status==='posted'?'Farah Ahmed':'',lines:[{account:source==='Payment Management'?(ref==='PAY-2802'?'1120 · bKash settlement wallet':'1110 · City Bank operating account'):'5300 · Facilities and utilities',description:memo,debit:amount,credit:0},{account:source==='Payment Management'?(ref==='PAY-2802'?'4200 · Training revenue':'4100 · Product sales'):'2100 · Trade payables',description:memo,debit:0,credit:amount}]}));
const financeJournalFilter={search:'',status:'',from:'',to:''};
const financeJournalAmount=value=>Number(value).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
function financeJournalStatus(status){return `<span class="fin-journal-status ${status}">${status}</span>`;}
function renderFinanceJournals(){const params=new URLSearchParams(location.hash.split('?')[1]||''),status=financeJournalFilter.status||params.get('status')||'',rows=financeJournals.filter(row=>(!financeJournalFilter.search||`${row.id} ${row.memo}`.toLowerCase().includes(financeJournalFilter.search.toLowerCase()))&&(!status||row.status===status));const body=rows.map(row=>`<tr><td><strong>${row.title}</strong><small>${row.id}</small></td><td>${row.date}</td><td>${financeJournalStatus(row.status)}${row.approval?`<span class="fin-approval">${row.approval}</span>`:''}</td><td class="fin-journal-memo">${esc(row.memo)}${row.source?`<small>${row.source} · ${row.ref||'No reference'}</small>`:''}</td><td class="fin-journal-totals"><span>Dr ${financeJournalAmount(row.amount)}</span><span>Cr ${financeJournalAmount(row.amount)}</span></td><td>${row.lineCount}</td><td><select data-fin-journal-action="${row.id}" aria-label="Actions for ${row.id}"><option value="">Actions ···</option><option value="view">View details</option>${row.status==='draft'&&row.approval!=='pending'?'<option value="post">Post journal</option>':''}${row.status==='draft'&&!row.approval?'<option value="submit">Submit for approval</option>':''}${row.approval==='pending'?'<option value="approve">Approve journal</option><option value="reject">Reject journal</option>':''}${row.status==='posted'?'<option value="reverse">Reverse journal</option>':''}</select></td></tr>`).join('');return `<div class="finance-mock">${financeHero('Journals','Create balanced draft journals, post them against open accounting periods, and reverse them through an audit-safe journal flow.',`<button class="btn primary" data-fin-journal-new>New journal</button><a class="btn" href="#/app/finance/journals/recurring">Recurring templates</a><button class="btn" data-fin-refresh>Refresh</button>`)}${financeCard('Journal entries',`<div class="fin-filters fin-journal-filters"><label>Search<input data-fin-journal-filter="search" value="${esc(financeJournalFilter.search)}" placeholder="Entry number or memo"></label><label>Status<select data-fin-journal-filter="status"><option value="">All statuses</option>${['draft','posted','reversed'].map(option=>`<option value="${option}" ${status===option?'selected':''}>${option[0].toUpperCase()+option.slice(1)}</option>`).join('')}</select></label><label>From<input type="date" data-fin-journal-filter="from" value="${financeJournalFilter.from}"></label><label>To<input type="date" data-fin-journal-filter="to" value="${financeJournalFilter.to}"></label><button class="btn" data-fin-journal-clear>Clear filters</button></div>${financeTable(['Journal','Posting date','Status','Memo','Totals','Lines','Actions'],body,'No journals match the current filters.')}<div class="fin-count">${rows.length} journal entries · FY 2025–26 · September posting period open</div>`,'','Search, review, and manage manual and source-generated journals.')}</div>`;}
const financeRecurringTemplates=[
  {id:'RJT-104',name:'Monthly rent accrual',frequency:'monthly',next:'01 Oct 2026',last:'01 Sep 2026',autoPost:false,status:'active',amount:13200,lines:2},
  {id:'RJT-103',name:'Office utilities allocation',frequency:'monthly',next:'01 Oct 2026',last:'01 Sep 2026',autoPost:true,status:'active',amount:4800,lines:2},
  {id:'RJT-102',name:'Quarterly insurance amortization',frequency:'quarterly',next:'01 Oct 2026',last:'01 Jul 2026',autoPost:false,status:'active',amount:6300,lines:2},
  {id:'RJT-101',name:'Training equipment depreciation',frequency:'monthly',next:'Not scheduled',last:'01 Aug 2026',autoPost:false,status:'paused',amount:2750,lines:2}
];
const financeRecurringFilter={search:'',status:''};
function renderFinanceRecurringJournals(){const rows=financeRecurringTemplates.filter(row=>(!financeRecurringFilter.search||`${row.name} ${row.frequency}`.toLowerCase().includes(financeRecurringFilter.search.toLowerCase()))&&(!financeRecurringFilter.status||row.status===financeRecurringFilter.status));const body=rows.map(row=>`<tr><td><strong>${esc(row.name)}</strong><small>${row.lines} journal lines</small></td><td>${row.frequency}</td><td>${row.next}</td><td>${row.last}</td><td><span class="fin-journal-status ${row.autoPost?'posted':'draft'}">${row.autoPost?'Auto-post':'Draft only'}</span></td><td>${financeJournalStatus(row.status)}</td><td><select data-fin-recurring-action="${row.id}" aria-label="Actions for ${row.name}"><option value="">Actions ···</option><option value="view">View details</option><option value="edit">Edit template</option><option value="run">Run now</option><option value="${row.status==='active'?'pause':'activate'}">${row.status==='active'?'Pause':'Activate'}</option></select></td></tr>`).join('');return `<div class="finance-mock">${financeHero('Recurring journals','Schedule reusable journal templates and control whether generated entries are posted automatically.',`<button class="btn" data-fin-refresh>Refresh</button><button class="btn primary" data-fin-recurring-new>New template</button>`)}<a class="fin-back-link" href="#/app/finance/journals">← Journal entries</a><div class="fin-recurring-summary">${[['Total templates',financeRecurringTemplates.length,'Reusable journal rules'],['Active',financeRecurringTemplates.filter(r=>r.status==='active').length,'Scheduled for generation'],['Paused',financeRecurringTemplates.filter(r=>r.status==='paused').length,'Not generating entries']].map(([label,value,note])=>`<div><span>${label}</span><strong>${value}</strong><small>${note}</small></div>`).join('')}</div>${financeCard('Templates',`<div class="fin-filters fin-recurring-filters"><label>Search templates<input data-fin-recurring-filter="search" value="${esc(financeRecurringFilter.search)}" placeholder="Name or frequency"></label><label>Status<select data-fin-recurring-filter="status"><option value="">All statuses</option><option value="active" ${financeRecurringFilter.status==='active'?'selected':''}>Active</option><option value="paused" ${financeRecurringFilter.status==='paused'?'selected':''}>Paused</option></select></label></div>${financeTable(['Template','Frequency','Next run','Last run','Posting','Status','Actions'],body,'No recurring journal templates match the current filters.')}`,'','Review the schedule, posting behavior, and most recent run for each template.')}</div>`;}
function financeJournalDetailDrawer(row){return `<div class="fin-journal-drawer"><div class="fin-journal-detail-grid">${[['Entry Number',row.id],['Status',row.status+(row.approval?' · '+row.approval:'')],['Posting Date',row.date],['Posted At',row.status==='posted'?'25 Sep 2026, 10:40 AM':'Not posted yet'],['Source',row.source||'Manual'],['Reversal Chain',row.status==='reversed'?'Reversed':'None']].map(([label,value])=>`<div><span>${label}</span><strong>${esc(value)}</strong></div>`).join('')}</div><h3>Audit Trail</h3><div class="fin-journal-audit"><div><span>Created by</span><strong>${row.createdBy}</strong><small>24 Sep 2026, 9:35 AM</small></div>${row.postedBy?`<div><span>Posted by</span><strong>${row.postedBy}</strong><small>25 Sep 2026, 10:40 AM</small></div>`:''}</div><div class="fin-journal-note"><strong>Memo</strong><p>${esc(row.memo)}</p></div>${financeTable(['Account','Description','Debit','Credit'],row.lines.map(line=>`<tr><td>${esc(line.account)}</td><td>${esc(line.description)}</td><td>${line.debit?financeJournalAmount(line.debit):'—'}</td><td>${line.credit?financeJournalAmount(line.credit):'—'}</td></tr>`).join(''),'No journal lines.')}<div class="fin-journal-drawer-actions"><button class="btn" data-action="close">Close</button></div></div>`;}
function financeJournalLineHtml(){return `<div class="fin-journal-line"><select aria-label="Account"><option value="">Select account</option>${financeAccounts.filter(a=>a.active&&a.postable).map(a=>`<option value="${a.id}">${a.code} · ${esc(a.name)}</option>`).join('')}</select><select aria-label="Cost center"><option value="">Optional</option><option>Dhaka Central</option><option>Training Operations</option></select><input aria-label="Line description" placeholder="Line description"><input aria-label="Debit" type="number" min="0" step="0.01" placeholder="0.00" data-fin-line-debit><input aria-label="Credit" type="number" min="0" step="0.01" placeholder="0.00" data-fin-line-credit><button class="btn" data-fin-line-remove aria-label="Remove journal line">×</button></div>`;}
function financeJournalCreateDrawer(){return `<div class="fin-journal-drawer"><p>Add journal lines with exactly matching debit and credit totals before saving the draft.</p><div class="fin-journal-meta"><label>Posting date<input type="date" value="2026-09-25" data-fin-post-date></label><label>Memo<textarea rows="3" placeholder="Explain the accounting purpose of this journal." data-fin-memo></textarea></label></div><div class="fin-journal-editor-head"><div><h3>Journal Lines</h3><p>Each line must carry either debit or credit, and the totals must balance before the draft can be saved.</p></div><button class="btn" data-fin-line-add>Add Line</button></div><div class="fin-journal-line headings"><span>Account</span><span>Cost center</span><span>Description</span><span>Debit</span><span>Credit</span><span></span></div><div data-fin-lines>${financeJournalLineHtml()}${financeJournalLineHtml()}</div><div class="fin-journal-balance"><div><span>Total Debit</span><strong data-fin-total-debit>0.00</strong></div><div><span>Total Credit</span><strong data-fin-total-credit>0.00</strong></div><b data-fin-balance-state>Out of balance</b></div><div class="fin-journal-error" data-fin-error hidden></div><div class="fin-journal-drawer-actions"><button class="btn" data-action="close">Close</button><button class="btn primary" data-fin-journal-save>Save Draft</button></div></div>`;}
function financeRecurringDrawer(row,readonly=false){return `<div class="fin-journal-drawer"><p>Define the schedule and the balanced journal that will be generated.</p><h3>Template details</h3><div class="fin-recurring-fields"><label>Template name *<input value="${esc(row?.name||'')}" placeholder="e.g. Monthly rent accrual" ${readonly?'disabled':''}></label><label>Frequency *<select ${readonly?'disabled':''}>${['weekly','monthly','quarterly','yearly'].map(f=>`<option ${row?.frequency===f?'selected':''}>${f}</option>`).join('')}</select></label><label>Start date *<input type="date" value="2026-09-01" ${readonly?'disabled':''}></label><label>End date<input type="date" ${readonly?'disabled':''}></label><label>Memo<textarea rows="2" placeholder="Explain the accounting purpose." ${readonly?'disabled':''}>${esc(row?.name||'')}</textarea></label></div><div class="fin-recurring-post"><h3>Posting behavior</h3><p>Choose whether generated journals are posted immediately or left as drafts for review.</p><label><input type="checkbox" ${row?.autoPost?'checked':''} ${readonly?'disabled':''}> Auto-post generated journals</label></div><div class="fin-journal-editor-head"><div><h3>Journal lines</h3><p>Debit and credit totals must balance before the template can be saved.</p></div>${readonly?'':'<button class="btn" data-fin-line-add>Add line</button>'}</div><div class="fin-journal-line headings"><span>Account</span><span>Cost center</span><span>Description</span><span>Debit</span><span>Credit</span><span></span></div><div data-fin-lines>${financeJournalLineHtml()}${financeJournalLineHtml()}</div><div class="fin-journal-balance"><div><span>Debit</span><strong data-fin-total-debit>0.00</strong></div><div><span>Credit</span><strong data-fin-total-credit>0.00</strong></div><b data-fin-balance-state>Out of balance</b></div><div class="fin-journal-drawer-actions"><button class="btn" data-action="close">${readonly?'Close':'Cancel'}</button>${readonly?'':`<button class="btn primary" data-fin-recurring-save>${row?'Update template':'Save template'}</button>`}</div></div>`;}
function financeJournalActionDrawer(action,row){const labels={post:'Confirm journal posting',reverse:'Create reversing journal',submit:'Submit for approval',approve:'Approve journal',reject:'Reject approval request',run:'Run recurring journal?',pause:'Pause recurring journal?',activate:'Activate recurring journal?'};return `<div class="fin-journal-drawer"><p>${action==='post'?`This will finalize ${row.id} in the current accounting period. Posted journals cannot be edited directly.`:action==='reverse'?`A new posted journal will be created with swapped debits and credits for ${row.id}. The original journal will be marked as reversed.`:`Review the impact of ${action} for ${row.id||row.name}.`}</p>${row.amount?`<div class="fin-journal-balance"><div><span>Debit</span><strong>${financeJournalAmount(row.amount)}</strong></div><div><span>Credit</span><strong>${financeJournalAmount(row.amount)}</strong></div><b>Balanced</b></div>`:''}${['reverse','reject'].includes(action)?'<label>Reason<textarea rows="4" placeholder="Explain this decision for the audit trail"></textarea></label>':''}<div class="fin-journal-drawer-actions"><button class="btn" data-action="close">Cancel</button><button class="btn primary" data-fin-action-confirm="${action}|${row.id}">${labels[action]||'Confirm'}</button></div></div>`;}
function financeJournalTotals(){const box=root.querySelector('[data-fin-lines]');if(!box)return;const debit=[...box.querySelectorAll('[data-fin-line-debit]')].reduce((sum,input)=>sum+Number(input.value||0),0),credit=[...box.querySelectorAll('[data-fin-line-credit]')].reduce((sum,input)=>sum+Number(input.value||0),0);root.querySelector('[data-fin-total-debit]').textContent=financeJournalAmount(debit);root.querySelector('[data-fin-total-credit]').textContent=financeJournalAmount(credit);const state=root.querySelector('[data-fin-balance-state]');state.textContent=debit>0&&Math.abs(debit-credit)<.001?'Balanced':'Out of balance';state.classList.toggle('balanced',debit>0&&Math.abs(debit-credit)<.001);}
root.addEventListener('input',event=>{const key=event.target.dataset.finJournalFilter;if(key)financeJournalFilter[key]=event.target.value;const recurringKey=event.target.dataset.finRecurringFilter;if(recurringKey)financeRecurringFilter[recurringKey]=event.target.value;if(event.target.matches('[data-fin-line-debit],[data-fin-line-credit]'))financeJournalTotals()});
root.addEventListener('change',event=>{if(event.target.dataset.finJournalFilter){financeJournalFilter[event.target.dataset.finJournalFilter]=event.target.value;render();return}if(event.target.dataset.finRecurringFilter){financeRecurringFilter[event.target.dataset.finRecurringFilter]=event.target.value;render();return}const journalId=event.target.dataset.finJournalAction;if(journalId){const action=event.target.value,row=financeJournals.find(j=>j.id===journalId);if(!action)return;activeAction=action==='view'?'Journal details':action==='post'?'Post journal':action==='reverse'?'Create reversing journal':action==='submit'?'Submit for approval':action==='approve'?'Approve journal':'Reject journal';activeOverlayHTML=action==='view'?financeJournalDetailDrawer(row):financeJournalActionDrawer(action,row);activeOverlayClass='fin-journal-overlay';drawer='original';render();return}const recurringId=event.target.dataset.finRecurringAction;if(recurringId){const action=event.target.value,row=financeRecurringTemplates.find(t=>t.id===recurringId);if(!action)return;activeAction=action==='view'?'Template details':action==='edit'?'Edit template':action==='run'?'Run recurring journal':action==='pause'?'Pause recurring journal':'Activate recurring journal';activeOverlayHTML=['view','edit'].includes(action)?financeRecurringDrawer(row,action==='view'):financeJournalActionDrawer(action,row);activeOverlayClass='fin-journal-overlay';drawer='original';render()}});
root.addEventListener('click',event=>{if(event.target.closest('[data-fin-journal-clear]')){Object.keys(financeJournalFilter).forEach(key=>financeJournalFilter[key]='');location.hash='#/app/finance/journals';render();return}if(event.target.closest('[data-fin-journal-new]')){activeAction='Create draft journal';activeOverlayHTML=financeJournalCreateDrawer();activeOverlayClass='fin-journal-overlay';drawer='original';render();return}if(event.target.closest('[data-fin-recurring-new]')){activeAction='New template';activeOverlayHTML=financeRecurringDrawer();activeOverlayClass='fin-journal-overlay';drawer='original';render();return}if(event.target.closest('[data-fin-line-add]')){root.querySelector('[data-fin-lines]')?.insertAdjacentHTML('beforeend',financeJournalLineHtml());return}if(event.target.closest('[data-fin-line-remove]')){const lines=root.querySelectorAll('.fin-journal-line:not(.headings)');if(lines.length>2){event.target.closest('.fin-journal-line')?.remove();financeJournalTotals()}return}if(event.target.closest('[data-fin-journal-save]')){const debit=Number(root.querySelector('[data-fin-total-debit]')?.textContent?.replaceAll(',','')),credit=Number(root.querySelector('[data-fin-total-credit]')?.textContent?.replaceAll(',','')),memo=root.querySelector('[data-fin-memo]')?.value.trim(),error=root.querySelector('[data-fin-error]');if(!memo||!debit||Math.abs(debit-credit)>.001){error.textContent='Add a memo and balanced debit and credit lines before saving.';error.hidden=false;return}const id=`JRN-${String(255+financeJournals.length-22).padStart(4,'0')}`;financeJournals.unshift({id,title:'Manual journal',date:'25 Sep 2026',status:'draft',memo,source:'',ref:'',amount:debit,lineCount:root.querySelectorAll('.fin-journal-line:not(.headings)').length,approval:'',createdBy:'Farah Ahmed',postedBy:'',lines:[{account:'1110 · City Bank operating account',description:memo,debit,credit:0},{account:'4100 · Product sales',description:memo,debit:0,credit}]});drawer='';flash('Sample draft journal saved in this browser preview.');return}if(event.target.closest('[data-fin-recurring-save]')){drawer='';flash('Sample recurring journal template saved.');return}const confirmation=event.target.closest('[data-fin-action-confirm]')?.dataset.finActionConfirm;if(confirmation){const [action,id]=confirmation.split('|'),row=financeJournals.find(j=>j.id===id)||financeRecurringTemplates.find(t=>t.id===id);if(row){if(action==='post')row.status='posted';if(action==='reverse')row.status='reversed';if(action==='submit')row.approval='pending';if(action==='approve'){row.approval='approved';row.status='posted'}if(action==='reject')row.approval='rejected';if(action==='pause')row.status='paused';if(action==='activate')row.status='active'}drawer='';flash(`Sample ${action} action recorded.`);return}});
